/* @autogenerated */
package net.civeira.phylax.common.infrastructure.config;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URL;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.eclipse.microprofile.config.Config;
import org.eclipse.microprofile.config.inject.ConfigProperty;

import io.smallrye.config.DotEnvConfigSourceProvider;
import io.smallrye.config.EnvConfigSource;
import io.smallrye.config.SmallRyeConfig;
import io.smallrye.config.SmallRyeConfigBuilder;
import io.smallrye.config.SysPropConfigSource;
import io.smallrye.config.source.yaml.YamlConfigSource;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.inject.Inject;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads a yaml file as an {@link IsolatedConfig}: it is not part of the application configuration,
 * so a functional block (for example its migration seed) can read its own file without declaring it
 * on {@code application.yaml}.
 *
 * <p>
 * For a path such as {@code migration/seed/oidc-seed.yaml} the sources are, from lower to higher
 * priority:
 * </p>
 * <ol>
 * <li>the classpath resource {@code migration/seed/oidc-seed.yaml};</li>
 * <li>the external file {@code <app.isolated-config.location>/migration/seed/oidc-seed.yaml}
 * (default location {@code config}, the directory mounted on deployments);</li>
 * <li>system properties and environment variables ({@code root.password} can be overridden with
 * {@code ROOT_PASSWORD}), which also resolve the {@code ${...}} expressions of the file.</li>
 * </ol>
 *
 * <p>
 * As on the application configuration, the {@code .env} file of the working directory completes the
 * environment variables (a real variable wins over the file).
 * </p>
 *
 * <p>
 * The active profiles of the application apply, so the file may define {@code "%dev":} values.
 * </p>
 */
@Slf4j
@ApplicationScoped
public class IsolatedConfigLoader {

  private static final int CLASSPATH_ORDINAL = 100;

  private static final int EXTERNAL_ORDINAL = 200;

  private static final int ENVIRONMENT_ORDINAL = 300;

  private final Path externalLocation;

  private final List<String> profiles;

  private final Map<String, String> environment;

  @Inject
  public IsolatedConfigLoader(final Config config,
      @ConfigProperty(name = "app.isolated-config.location",
          defaultValue = "config") final String externalLocation) {
    this(Path.of(externalLocation), config.unwrap(SmallRyeConfig.class).getProfiles(),
        environment(dotEnvFile(), System.getenv()));
  }

  IsolatedConfigLoader(final Path externalLocation, final List<String> profiles,
      final Map<String, String> environment) {
    this.externalLocation = externalLocation;
    this.profiles = profiles;
    this.environment = environment;
  }

  /**
   * @param path the path of the yaml file, relative to the classpath and to the external location
   * @return the isolated configuration; if no file is found it is empty and
   *         {@link IsolatedConfig#exists()} is false
   */
  public IsolatedConfig load(final String path) {
    SmallRyeConfigBuilder builder =
        new SmallRyeConfigBuilder().addDefaultInterceptors().withProfiles(profiles).withSources(
            new SysPropConfigSource(), new EnvConfigSource(environment, ENVIRONMENT_ORDINAL));
    boolean found = false;
    URL classpath = Thread.currentThread().getContextClassLoader().getResource(path);
    if (null != classpath) {
      builder.withSources(yaml(classpath, CLASSPATH_ORDINAL));
      found = true;
    }
    Path external = externalLocation.resolve(path);
    if (Files.isRegularFile(external)) {
      builder.withSources(yaml(url(external), EXTERNAL_ORDINAL));
      found = true;
    }
    if (!found) {
      log.warn("Isolated config {} not found on the classpath nor on {}", path, externalLocation);
    }
    return new IsolatedConfig(path, found, builder.build());
  }

  /**
   * @param dotEnv the {@code .env} file, it may not exist
   * @param variables the environment variables of the process
   * @return the variables of the {@code .env} file overridden by the environment variables
   */
  static Map<String, String> environment(final Path dotEnv, final Map<String, String> variables) {
    Map<String, String> environment = new HashMap<>();
    DotEnvConfigSourceProvider
        .dotEnvSources(dotEnv.toUri().toString(), Thread.currentThread().getContextClassLoader())
        .forEach(source -> environment.putAll(source.getProperties()));
    environment.putAll(variables);
    return environment;
  }

  private static Path dotEnvFile() {
    return Path.of(System.getProperty("user.dir"), ".env");
  }

  private static YamlConfigSource yaml(final URL url, final int ordinal) {
    try {
      return new YamlConfigSource(url, ordinal);
    } catch (IOException ex) {
      throw new UncheckedIOException("Unable to read " + url, ex);
    }
  }

  private static URL url(final Path path) {
    try {
      return path.toUri().toURL();
    } catch (IOException ex) {
      throw new UncheckedIOException("Unable to read " + path, ex);
    }
  }
}
